
#app-content-wrapper {
  .ncdownloader-form-wrapper {
    position: relative;
    width: 100%;
  }

  .form-section {
    width: 100%;
    display: flex;
    flex-flow: column;
    gap: 16px;
  }
}

@media only screen and (max-width: 1024px) {
  #app-content-wrapper {
    #ncdownloader-form-wrapper {
      margin: 4px;
    }
  }
}
