
@import "../css/variables.scss";

.main-form {
  display: flex;
  flex-wrap: wrap;
  width: 100%;
  gap: 12px;

  .type-selector {
    display: flex;
    gap: 0;
    border-radius: var(--border-radius-pill, 22px);
    overflow: hidden;
    background-color: var(--color-background-dark, var(--color-background-hover));
    padding: 2px;

    .type-btn {
      padding: 6px 16px;
      border: none;
      background: transparent;
      color: var(--color-text-maxcontrast);
      font-size: 13px;
      font-weight: 500;
      cursor: pointer;
      border-radius: var(--border-radius-pill, 22px);
      transition: all 0.15s ease-in-out;
      white-space: nowrap;

      &.active {
        background-color: var(--color-primary);
        color: var(--color-primary-text);
      }

      &:not(.active):hover {
        color: var(--color-main-text);
        background-color: var(--color-background-hover);
      }
    }
  }

  .action-group {
    flex: 1;
    min-width: 280px;
  }

  .download-input-container {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    width: 100%;

    // Text input styling
    :deep(input[type="text"]) {
      flex: 1;
      min-width: 200px;
      padding: 8px 12px;
      border: 1px solid var(--color-border);
      border-radius: var(--border-radius);
      background-color: var(--color-main-background);
      color: var(--color-main-text);
      font-size: 14px;
      height: $column-height;

      &:focus {
        border-color: var(--color-primary);
        outline: none;
        box-shadow: 0 0 0 2px var(--color-primary-light);
      }

      &::placeholder {
        color: var(--color-text-maxcontrast);
      }
    }
  }

  .download-controls {
    display: flex;
    align-items: center;
    gap: 6px;
    height: $column-height;

    select {
      height: 100%;
      padding: 0 10px;
      border: 1px solid var(--color-border);
      border-radius: var(--border-radius);
      background-color: var(--color-main-background);
      color: var(--color-main-text);
      font-size: 14px;

      &:focus {
        border-color: var(--color-primary);
        outline: none;
      }
    }

    button.primary {
      height: 100%;
      white-space: nowrap;
      padding: 0 20px;
    }
  }

  // Search input container
  :deep(.search-input-container) {
    display: flex;
    gap: 8px;
    align-items: center;

    input[type="text"] {
      flex: 1;
      min-width: 150px;
      padding: 8px 12px;
      border: 1px solid var(--color-border);
      border-radius: var(--border-radius);
      background-color: var(--color-main-background);
      color: var(--color-main-text);
      height: $column-height;

      &:focus {
        border-color: var(--color-primary);
        outline: none;
        box-shadow: 0 0 0 2px var(--color-primary-light);
      }
    }

    select {
      height: $column-height;
      padding: 0 10px;
      border: 1px solid var(--color-border);
      border-radius: var(--border-radius);
      background-color: var(--color-main-background);
      color: var(--color-main-text);
    }
  }
}

@media only screen and (max-width: 1024px) {
  .main-form {
    flex-flow: column;
    gap: 8px;

    .type-selector {
      width: 100%;
      justify-content: center;
      .type-btn {
        flex: 1;
        text-align: center;
      }
    }

    .download-input-container {
      flex-flow: column;

      :deep(input[type="text"]) {
        width: 100%;
      }

      .download-controls {
        width: 100%;
        justify-content: center;
      }
    }
  }
}
